_CORE_SRC = '# Diagnosis:\n# The reported losses to c2 occur in both seats; the small sample does not establish\n# a seat-specific weakness. The champion already accounts for denial, upkeep and\n# arrival time. Its important restriction is that every candidate trajectory travels\n# immediately along one shortest path, then stays at its destination for the entire\n# horizon. It cannot plan to serve an intermediate node, wait through a forecast\n# spike, or earn locally before returning home. This can lose against a simpler\n# allocator that happens to retain the right locally productive drones.\n#\n# A second weakness is treating fractional predicted enemy counts as real drones.\n# "Half a drone certainly present" and "one drone present with probability one half"\n# have different marginal values under the nonlinear sharing rule.\n#\n# Improvements:\n# 1. Coordinate best response over unrestricted, legal time-expanded paths, using\n#    the exact forecast and charging upkeep at every intermediate position.\n# 2. Evaluate a discrete ensemble of stationary, revenue-seeking and margin-seeking\n#    opponents. Learn its weights from observed one-turn prediction errors.\n# Keep start-of-turn legality, aggregation, warm intentions and bounded computation.\n\nimport math\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\n\ndef build_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        a, b = int(a), int(b)\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for v in range(n):\n        adjacency[v] = sorted(set(adjacency[v]))\n    # Staying is considered first, so exact ties do not cause needless movement.\n    choices = [[v] + adjacency[v] for v in range(n)]\n    return adjacency, choices\n\n\ndef marginal_tables(demands, scenarios, home, denial, weights, total):\n    """Expected marginal score, not score against expected enemy occupancy."""\n    horizon = len(weights)\n    n = len(demands)\n    tables = []\n    for k in range(horizon):\n        layer = []\n        for v in range(n):\n            d = demands[v][k]\n            values = [0.0] * (total + 2)\n            if d > 0.0:\n                for probability, enemy_path in scenarios:\n                    enemy = enemy_path[k][v]\n                    enemy_capacity = 5.0 * enemy\n                    for count in range(total + 2):\n                        denominator = max(5.0 * count + enemy_capacity, d)\n                        values[count] += (\n                            probability * (5.0 * count - denial * enemy_capacity)\n                            * d / denominator\n                        )\n            cost = 0.0 if v == home else 2.0\n            layer.append([\n                weights[k] * (values[count + 1] - values[count] - cost)\n                for count in range(total + 1)\n            ])\n        tables.append(layer)\n    return tables\n\n\ndef initialize_units(have, home, horizon, pending, adjacency):\n    n = len(have)\n    units = []\n    occupancy = [[0] * n for _ in range(horizon)]\n    for source in sorted(range(n), key=lambda v: (v == home, v)):\n        old = pending.get(source, [])\n        for j in range(have[source]):\n            path = list(old[j]) if j < len(old) else []\n            if not path:\n                path = [source] * horizon\n            elif len(path) < horizon:\n                path.extend([path[-1]] * (horizon - len(path)))\n            path = path[:horizon]\n            # Warm starts are optional. Validate them independently of history.\n            position = source\n            valid = True\n            for destination in path:\n                if not 0 <= destination < n:\n                    valid = False\n                    break\n                if destination != position and destination not in adjacency[position]:\n                    valid = False\n                    break\n                position = destination\n            if not valid:\n                path = [source] * horizon\n            sticky = path[:]\n            units.append([source, path, sticky])\n            for k, destination in enumerate(path):\n                occupancy[k][destination] += 1\n    return units, occupancy\n\n\ndef optimize_paths(have, home, tables, weights, adjacency, choices,\n                   pending, passes, deadline):\n    """Coordinate ascent; each single-drone update is an exact graph DP."""\n    horizon = len(tables)\n    n = len(have)\n    units, occupancy = initialize_units(\n        have, home, horizon, pending, adjacency\n    )\n    for iteration in range(passes):\n        changed = False\n        for unit in units:\n            if time.perf_counter() >= deadline:\n                return units, occupancy\n            source, old_path, sticky = unit\n            for k, v in enumerate(old_path):\n                occupancy[k][v] -= 1\n\n            future = [0.0] * n\n            policies = [None] * horizon\n            for k in range(horizon - 1, -1, -1):\n                table = tables[k]\n                occupied = occupancy[k]\n                # Small fixed preference for last turn\'s intentions, not for the\n                # most recent coordinate update. This stabilizes real movement.\n                preference = 0.12 if k == 0 else 0.025 * weights[k]\n                reward = [\n                    table[v][occupied[v]]\n                    + (preference if v == sticky[k] else 0.0)\n                    for v in range(n)\n                ]\n                movement_cost = 0.018 * weights[k]\n                current = [0.0] * n\n                policy = [0] * n\n                for position in range(n):\n                    best_destination = position\n                    best_value = reward[position] + future[position]\n                    for destination in adjacency[position]:\n                        value = (reward[destination] + future[destination]\n                                 - movement_cost)\n                        if value > best_value + 1e-10:\n                            best_value = value\n                            best_destination = destination\n                    current[position] = best_value\n                    policy[position] = best_destination\n                policies[k] = policy\n                future = current\n\n            position = source\n            path = []\n            for k in range(horizon):\n                position = policies[k][position]\n                path.append(position)\n                occupancy[k][position] += 1\n            if path != old_path:\n                changed = True\n            unit[1] = path\n        if not changed:\n            break\n    return units, occupancy\n\n\ndef next_pending(units):\n    result = {}\n    for source, path, sticky in units:\n        if path:\n            result.setdefault(path[0], []).append(tuple(path[1:] + [path[-1]]))\n    for source in result:\n        result[source].sort()\n    return result\n\n\ndef validated_action(units, have, adjacency):\n    aggregate = {}\n    for source, path, sticky in units:\n        if path and path[0] != source:\n            pair = (source, path[0])\n            aggregate[pair] = aggregate.get(pair, 0) + 1\n    available = list(have)\n    n = len(have)\n    action = []\n    for (source, destination), count in sorted(aggregate.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if destination not in adjacency[source]:\n            continue\n        count = min(int(count), available[source])\n        if count > 0:\n            action.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_turn = None\n        self.pending = {}\n        self.enemy_pending = [{}, {}]\n        self.model_weights = [0.20, 0.40, 0.40]\n        self.last_predictions = None\n        self.bad_reports = 0\n        self.idle_turns = 0\n        self.previous_enemy = None\n\n    def act(self, obs):\n        started = time.perf_counter()\n        budget = max(0.0, float(TIME_BUDGET))\n        deadline = started + 0.57 * budget\n\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None:\n            self.map_data = build_map(n, obs.get("edges", []))\n        adjacency, choices = self.map_data\n        home = int(obs["player_base"])\n        enemy_home = int(obs["opponent_base"])\n        have = [int(x) for x in obs.get("player_drones", [0] * n)]\n        enemy = [int(x) for x in obs.get("opponent_drones", [0] * n)]\n        turn = int(obs.get("turn", 0))\n        total = sum(have)\n        if total <= 0 or turn >= 100:\n            return []\n\n        consecutive = (\n            self.previous_turn is not None and turn == self.previous_turn + 1\n        )\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0)):\n            self.bad_reports += 1\n\n        if consecutive and self.last_predictions is not None:\n            likelihoods = []\n            for prediction in self.last_predictions:\n                error = 0.5 * sum(\n                    abs(enemy[v] - prediction[v]) for v in range(n)\n                )\n                likelihoods.append(math.exp(-0.24 * error))\n            posterior = [\n                self.model_weights[j] * likelihoods[j] for j in range(3)\n            ]\n            normalizer = sum(posterior)\n            if normalizer > 0.0:\n                self.model_weights = [\n                    0.025 + 0.925 * p / normalizer for p in posterior\n                ]\n        if consecutive and self.previous_enemy == enemy:\n            self.idle_turns += 1\n        else:\n            self.idle_turns = 0\n        self.previous_enemy = enemy[:]\n        self.previous_turn = turn\n\n        # After repeated feedback errors use the same checked builder, but only\n        # one-step plans without warm starts or multi-pass refinement.\n        conservative = self.bad_reports >= 2\n        horizon = min(1 if conservative else 13, 100 - turn)\n        weights = [0.94 ** k for k in range(horizon)]\n        raw = obs.get("demand_forecast", [])\n        demands = []\n        for v in range(n):\n            row = list(raw[v]) if v < len(raw) and raw[v] else [0.0]\n            tail = 0.65 * float(row[-1]) + 0.35 * sum(row) / len(row)\n            demands.append([\n                max(0.0, float(row[k]) if k < len(row) else tail)\n                for k in range(horizon)\n            ])\n\n        # Three discrete scenarios. Each active model plans legal paths with\n        # actual travel upkeep; neither assumes instantaneous global allocation.\n        stationary_enemy = [enemy[:] for _ in range(horizon)]\n        stationary_us = [have[:] for _ in range(horizon)]\n        enemy_scenarios = [stationary_enemy]\n        updated_enemy_pending = []\n        enemy_total = sum(enemy)\n\n        for model in range(2):\n            model_tables = marginal_tables(\n                demands, [(1.0, stationary_us)], enemy_home,\n                float(model), weights, enemy_total\n            )\n            model_deadline = min(\n                deadline, started + (0.13 + 0.13 * model) * budget\n            )\n            warm = self.enemy_pending[model] if consecutive else {}\n            model_units, model_occupancy = optimize_paths(\n                enemy, enemy_home, model_tables, weights, adjacency, choices,\n                warm, 2 if not conservative else 1, model_deadline\n            )\n            enemy_scenarios.append(model_occupancy)\n            updated_enemy_pending.append(next_pending(model_units))\n        self.enemy_pending = updated_enemy_pending\n        self.last_predictions = [path[0][:] for path in enemy_scenarios]\n\n        probabilities = self.model_weights[:]\n        if self.idle_turns >= 3 and enemy[enemy_home] == enemy_total:\n            probabilities = [0.98, 0.01, 0.01]\n        scenarios = list(zip(probabilities, enemy_scenarios))\n\n        own_tables = marginal_tables(\n            demands, scenarios, home, 1.0, weights, total\n        )\n        warm = self.pending if consecutive and not conservative else {}\n        units, occupancy = optimize_paths(\n            have, home, own_tables, weights, adjacency, choices, warm,\n            1 if conservative else 4, deadline\n        )\n        self.pending = next_pending(units)\n\n        # Every path edge was checked or generated from adjacency. Independently\n        # aggregate and replay the first step using only start-of-turn counts.\n        return validated_action(units, have, adjacency)\n'
