_FALLBACK_SRC = '# Action: "[(from_node, to_node, count), ...]"\n# Payout: "served_i = capacity_i * demand / max(total_capacity, demand)",\n# where "capacity_i = drones_i * drone_capacity" and capacity is 5 per drone.\n# Cost: "UPKEEP = 2.0" per drone away from its own base after movement.\n# Each drone moves at most one edge, using start-of-turn availability only.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    adjacency = [sorted(set(row)) for row in adjacency]\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for other in adjacency[node]:\n                if row[other] == -1:\n                    row[other] = row[node] + 1\n                    queue.append(other)\n        distances.append(row)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if distances[source][target] > 0:\n                for neighbor in adjacency[source]:\n                    if distances[neighbor][target] == distances[source][target] - 1:\n                        next_hop[source][target] = neighbor\n                        break\n    return adjacency, distances, next_hop\n\n\ndef served(own_drones, opponent_drones, demand):\n    own_capacity = DRONE_CAPACITY * own_drones\n    total_capacity = DRONE_CAPACITY * (own_drones + opponent_drones)\n    denominator = max(total_capacity, demand)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * demand / denominator\n\n\ndef return_cost(distance, turns_left):\n    # On the last edge into home, upkeep is already zero.\n    if distance < 0:\n        return float("inf")\n    return UPKEEP * min(max(0, distance - 1), turns_left)\n\n\ndef plan_moves(obs, distances, next_hop):\n    n = int(obs["n_nodes"])\n    base = int(obs["player_base"])\n    enemy_base = int(obs["opponent_base"])\n    own = obs["player_drones"]\n    opponent = obs["opponent_drones"]\n    forecast = obs["demand_forecast"]\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    if remaining == 0 or not forecast:\n        return {}\n\n    horizon = min(remaining, min((len(row) for row in forecast), default=0))\n    if horizon == 0:\n        return {}\n\n    assigned = [0] * n\n    proposed = {}\n\n    # Already deployed drones get first refusal on profitable locations.\n    # This also avoids deploying reserves to replace drones already on site.\n    sources = sorted(range(n), key=lambda s: (s == base, s))\n    for source in sources:\n        for _ in range(max(0, int(own[source]))):\n            home_distance = distances[source][base]\n            baseline = -return_cost(home_distance, remaining)\n            best_target = base\n            best_rank = 0.0\n\n            candidates = sorted(\n                range(n),\n                key=lambda target: (\n                    distances[source][target] if distances[source][target] >= 0 else n + 1,\n                    target != source,\n                    target,\n                ),\n            )\n            for target in candidates:\n                if target == base or target == enemy_base:\n                    continue\n                # Do not initiate marginal contests. The payout helper still\n                # accounts for the opponent\'s capacity explicitly.\n                if opponent[target] > 0:\n                    continue\n                distance = distances[source][target]\n                if distance < 0:\n                    continue\n                arrival = max(0, distance - 1)\n                if arrival >= horizon:\n                    continue\n\n                count = assigned[target]\n                margins = [\n                    served(count + 1, opponent[target], forecast[target][k])\n                    - served(count, opponent[target], forecast[target][k])\n                    for k in range(arrival, horizon)\n                ]\n                # Never allocate a speculative marginal drone to a location\n                # that cannot clearly cover its upkeep throughout the window.\n                if not margins or min(margins) < UPKEEP + 0.8:\n                    continue\n\n                # Ignore any earnings along the route: conservative accounting.\n                value = sum(margins) - UPKEEP * horizon\n                if horizon < remaining:\n                    value -= return_cost(\n                        distances[target][base], remaining - horizon\n                    )\n                improvement = value - baseline\n\n                # New trips must pay for travel and eventual return, plus a\n                # meaningful safety cushion. Staying has a smaller hurdle.\n                hurdle = 0.25 if target == source else 2.5\n                if improvement <= hurdle:\n                    continue\n                rank = (improvement - hurdle) / (1.0 + 0.7 * distance)\n                if target == source:\n                    rank += 0.3\n                if rank > best_rank + 1e-9:\n                    best_rank = rank\n                    best_target = target\n\n            if best_target != base:\n                assigned[best_target] += 1\n            if best_target != source:\n                hop = next_hop[source][best_target]\n                if hop >= 0:\n                    key = (source, hop)\n                    proposed[key] = proposed.get(key, 0) + 1\n\n    return proposed\n\n\ndef legal_action(proposed, start_counts, adjacency):\n    available = [max(0, int(value)) for value in start_counts]\n    n = len(available)\n    action = []\n    for (source, target), requested in sorted(proposed.items()):\n        source, target = int(source), int(target)\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if source == target or target not in adjacency[source]:\n            continue\n        count = min(max(0, int(requested)), available[source])\n        if count > 0:\n            action.append((int(source), int(target), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(a), int(b)) for a, b in edges))\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n\n        adjacency, distances, next_hop = self.map_data\n        # A bad-feedback observation uses a simple, validated retreat. No\n        # history is needed, so skipped or nonconsecutive calls are harmless.\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            base = int(obs["player_base"])\n            proposed = {}\n            for source, count in enumerate(obs["player_drones"]):\n                hop = next_hop[source][base]\n                if source != base and hop >= 0 and count > 0:\n                    proposed[(source, hop)] = int(count)\n        else:\n            proposed = plan_moves(obs, distances, next_hop)\n        return legal_action(proposed, obs["player_drones"], adjacency)\n'
